Nothing here reads or changes the decimal context: Decimal values are
rounded with exact integer arithmetic, or with a `quantize` that names its
rounding.
"""

from __future__ import annotations

import math
from decimal import ROUND_DOWN, Decimal

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check_method(method) -> None:
    if not isinstance(method, str) or method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")


def _check_step(step) -> None:
    if not isinstance(step, Decimal):
        raise TypeError("step must be a Decimal")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be a positive decimal")


def _coefficient(d: Decimal) -> int:
    return int("".join(map(str, d.as_tuple().digits)))


def _magnitude(d: Decimal, exponent: int) -> int:
    """|d| as an integer count of 10**exponent (exact; exponent <= d's exponent)."""
    return _coefficient(d) * 10 ** (d.as_tuple().exponent - exponent)


def _build(negative: bool, coefficient: int, exponent: int) -> Decimal:
    return Decimal((1 if negative else 0, tuple(int(c) for c in str(coefficient)), exponent))


def _steps(magnitude: int, unit: int, method: str) -> int:
    """`magnitude` in units of `unit`, rounded to a whole number of units."""
    q, r = divmod(magnitude, unit)
    if method == DOWN:
        return q
    twice = 2 * r
    if twice > unit or (twice == unit and (method == HALF_UP or q % 2 == 1)):
        return q + 1
    return q


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; `method` decides ties and direction.

    The result has the exponent of `step` and the sign of `value`.
    """
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    _check_method(method)
    _check_step(step)
    if not value.is_finite():
        # NaN passes through, an infinity raises InvalidOperation.
        return value.quantize(step, rounding=ROUND_DOWN)
    exponent = min(value.as_tuple().exponent, step.as_tuple().exponent)
    unit = _magnitude(step, exponent)
    count = _steps(_magnitude(value, exponent), unit, method)
    return _build(value.is_signed(), count * _coefficient(step), step.as_tuple().exponent)


def _add(a: tuple, b: tuple) -> tuple:
    """Sum of two (negative, magnitude) pairs, with the sign Decimal gives an exact zero."""
    (an, am), (bn, bm) = a, b
    if an == bn:
        return an, am + bm
    if am == bm:
        return False, 0
    return (an, am - bm) if am > bm else (bn, bm - am)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, each a multiple of `step`, adding up to the rounded sum.

    Each amount is cut down to the step; what the cuts lost against the sum
    rounded half up goes on the last amount that is not zero.
    """
    amounts = list(amounts)
    if not all(isinstance(a, Decimal) for a in amounts) or not isinstance(step, Decimal):
        raise TypeError("amounts and step must be Decimal")
    _check_step(step)
    if not amounts:
        return []
    if not all(a.is_finite() for a in amounts):
        parts = [a.quantize(step, rounding=ROUND_DOWN) for a in amounts]
        whole = sum(amounts, Decimal("0")).quantize(step, rounding=ROUND_DOWN)
        rest = whole - sum(parts, Decimal(0).quantize(step))
        for i in range(len(parts) - 1, -1, -1):
            if amounts[i] != 0:
                parts[i] += rest
                break
        return parts
    es = step.as_tuple().exponent
    m = min([es] + [a.as_tuple().exponent for a in amounts])
    unit = _magnitude(step, m)
    cuts = [(a.is_signed(), _magnitude(a, m) // unit * unit) for a in amounts]
    exact = (False, 0)
    for a in amounts:
        exact = _add(exact, (a.is_signed(), _magnitude(a, m)))
    whole = (exact[0], _steps(exact[1], unit, HALF_UP) * unit)
    cut_sum = (False, 0)
    for c in cuts:
        cut_sum = _add(cut_sum, c)
    rest = _add(whole, (not cut_sum[0], cut_sum[1]))
    parts = list(cuts)
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    cs = _coefficient(step)
    return [_build(neg, mag // unit * cs, es) for neg, mag in parts]


def legacy_cents(value: float, places: int = 2) -> float:
    """A float amount as the old customer system settled it: binary floating point, half up."""
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    """`value` written with `places` digits after the point, rounded by `method`."""
    if isinstance(places, bool) or not isinstance(places, int):
        raise TypeError("places must be an int")
    if places < 0:
        raise ValueError("places must not be negative")
    if isinstance(value, float):
        _check_method(method)
        if method != HALF_EVEN:
            raise ValueError("a float can only be written half to even")
        return format(value, f".{places}f")
    if not isinstance(value, Decimal):
        raise TypeError("value must be a float or a Decimal")
    return format(round_amount(value, _build(False, 1, -places), method), "f")
